
    create table autori (
        id_autore bigint generated by default as identity,
        biografia TEXT,
        cognome varchar(255) not null,
        nazionalita varchar(255),
        nome varchar(255) not null,
        primary key (id_autore)
    );

    create table carrello (
        id_carrello bigint generated by default as identity,
        id_utente bigint not null unique,
        primary key (id_carrello)
    );

    create table carrello_items (
        prezzo_unitario_storico numeric(10,2),
        quantita integer not null,
        id_carrello bigint not null,
        id_carrello_item bigint generated by default as identity,
        id_formato bigint not null,
        primary key (id_carrello_item),
        unique (id_carrello, id_formato)
    );

    create table categorie (
        id_categoria bigint generated by default as identity,
        descrizione TEXT,
        nome varchar(255) not null unique,
        primary key (id_categoria)
    );

    create table editori (
        id_editore bigint generated by default as identity,
        descrizione TEXT,
        nome varchar(255) not null unique,
        primary key (id_editore)
    );

    create table formato_libro (
        attivo boolean,
        prezzo_listino numeric(10,2) not null,
        quantita_magazzino integer,
        id_formato bigint generated by default as identity,
        id_libro bigint not null,
        codice_isbn varchar(13) unique,
        tipo_copertina varchar(20) check ((tipo_copertina in ('RIGIDA','FLESSIBILE'))),
        tipo_supporto varchar(20) not null check ((tipo_supporto in ('CARTACEO','EBOOK'))),
        copertina_mime_type varchar(50),
        copertina BYTEA,
        primary key (id_formato),
        unique (id_libro, tipo_supporto, tipo_copertina)
    );

    create table indirizzi (
        is_predefinito boolean,
        provincia varchar(2),
        cap varchar(5),
        id_indirizzo bigint generated by default as identity,
        id_utente bigint not null,
        civico varchar(255),
        comune varchar(255),
        note_consegna TEXT,
        paese varchar(255),
        via varchar(255),
        primary key (id_indirizzo)
    );

    create table libri (
        id_autore bigint not null,
        id_editore bigint not null,
        id_libro bigint generated by default as identity,
        descrizione TEXT,
        titolo varchar(255) not null,
        primary key (id_libro)
    );

    create table libri_categorie (
        id_categoria bigint not null,
        id_libro bigint not null,
        primary key (id_categoria, id_libro)
    );

    create table ordine_items (
        prezzo_unitario_storico numeric(10,2) not null,
        quantita_ordinata integer not null,
        id_formato bigint not null,
        id_ordine bigint not null,
        id_ordine_item bigint generated by default as identity,
        primary key (id_ordine_item),
        unique (id_ordine, id_id_formato)
    );

    create table ordini (
        prezzo_totale numeric(10,2) not null,
        data_creazione_ordine timestamp(6),
        id_indirizzo bigint,
        id_ordine bigint generated by default as identity,
        id_utente bigint not null,
        metodo_pagamento varchar(255) not null check ((metodo_pagamento in ('CARTA','PAYPAL','CONSEGNA','BONIFICO'))),
        stato_ordine varchar(255) not null check ((stato_ordine in ('IN_ATTESA','SPEDITO','CONSEGNATO'))),
        primary key (id_ordine)
    );

    create table profili_utente (
        id_profilo bigint generated by default as identity,
        id_utente bigint unique,
        cognome varchar(255),
        nome varchar(255),
        numero_telefono varchar(255),
        primary key (id_profilo)
    );

    create table recensioni (
        valutazione smallint not null,
        data_pubblicazione timestamp(6),
        id_libro bigint,
        id_recensione bigint generated by default as identity,
        id_utente bigint,
        testo TEXT,
        primary key (id_recensione),
        unique (id_utente, id_libro)
    );

    create table utenti (
        id_utente bigint generated by default as identity,
        email varchar(100) not null unique,
        password varchar(255) not null,
        ruolo varchar(255) check ((ruolo in ('USER','ADMIN'))),
        primary key (id_utente)
    );

    create table wishlist (
        id_formato bigint,
        id_utente bigint,
        id_wishlist bigint generated by default as identity,
        primary key (id_wishlist),
        unique (id_utente, id_formato)
    );

